import{n as e}from"./rolldown-runtime-Cyuzqnbw.js";import{A as t}from"./framer-Be3hPn0e.js";import{ir as n,t as r,v as i}from"./icons-DTR6_mEc.js";import{n as a,t as o}from"./ArticleLayout-Ym4RT06s.js";var s,c,l=e((()=>{r(),s=[{"@context":`https://schema.org`,"@type":`Article`,headline:`Dossier carte grise bloqué sur l'ANTS : pourquoi, et comment le débloquer`,description:`Dossier de carte grise bloqué sur l'ANTS ? Causes fréquentes, délais réels et recours, dont le passage par un professionnel habilité pour débloquer vite.`,author:{"@type":`Organization`,name:`Evidence Assurances`},publisher:{"@type":`Organization`,name:`AssuTempo`,logo:{"@type":`ImageObject`,url:`https://assutempo.fr/logo.png`}},mainEntityOfPage:`https://assutempo.fr/articles/carte-grise-ants-bloquee`,datePublished:`2026-07-30`,dateModified:`2026-07-30`},{"@context":`https://schema.org`,"@type":`BreadcrumbList`,itemListElement:[{"@type":`ListItem`,position:1,name:`Accueil`,item:`https://assutempo.fr`},{"@type":`ListItem`,position:2,name:`Articles`,item:`https://assutempo.fr/articles`},{"@type":`ListItem`,position:3,name:`Dossier carte grise bloqué sur l'ANTS : pourquoi, et comment le débloquer`,item:`https://assutempo.fr/articles/carte-grise-ants-bloquee`}]},{"@context":`https://schema.org`,"@type":`FAQPage`,mainEntity:[{"@type":`Question`,name:`Pourquoi mon dossier de carte grise reste-t-il bloqué sur le site de l'ANTS ?`,acceptedAnswer:{"@type":`Answer`,text:`Le plus souvent à cause d'une pièce refusée par le contrôle automatique : justificatif de domicile trop ancien ou mal nommé, photo d'identité illisible, contrôle technique expiré, ou code de cession expiré après 15 jours. Un incident technique ponctuel sur le portail est aussi possible, sans lien avec votre dossier.`}},{"@type":`Question`,name:`Combien de temps l'ANTS met-il normalement à traiter une demande de carte grise ?`,acceptedAnswer:{"@type":`Answer`,text:`Les demandes sont traitées dans l'ordre d'arrivée, sans possibilité d'accélération une fois le dossier accepté. Le délai varie fortement selon le département et la charge du service instructeur : vérifiez l'avancement réel depuis votre espace personnel ANTS plutôt que de vous fier à une moyenne.`}},{"@type":`Question`,name:`Que faire si l'ANTS ne répond pas du tout à ma demande ?`,acceptedAnswer:{"@type":`Answer`,text:`En l'absence de réponse à une réclamation écrite, vous pouvez saisir le médiateur des cartes grises (service-public.gouv.fr). En cas de refus explicite, un recours gracieux est possible via le téléservice de l'ANTS, puis un appel auprès du ministère de l'Intérieur si le recours n'aboutit pas.`}},{"@type":`Question`,name:`Un professionnel habilité peut-il débloquer un dossier plus vite que l'ANTS en direct ?`,acceptedAnswer:{"@type":`Answer`,text:`Souvent oui, pour la partie diagnostic et redépôt : il a un accès direct au système d'immatriculation des véhicules (SIV) et peut identifier le motif exact du blocage, y compris pendant un incident sur le portail public. Cette assistance a un coût, contrairement au dépôt en direct sur l'ANTS.`}},{"@type":`Question`,name:`Puis-je rouler si mon dossier de carte grise est bloqué depuis plus d'un mois ?`,acceptedAnswer:{"@type":`Answer`,text:`Pas avec un certificat provisoire d'immatriculation expiré : mieux vaut vérifier l'avancement du dossier et solliciter un renouvellement auprès du professionnel ou du service qui le suit. L'assurance, elle, reste obligatoire sans exception, quel que soit l'état du dossier de carte grise.`}},{"@type":`Question`,name:`Comment saisir le médiateur des cartes grises en cas de refus ou de silence prolongé ?`,acceptedAnswer:{"@type":`Answer`,text:`Après une réclamation écrite restée sans réponse satisfaisante auprès de l'ANTS, le médiateur des cartes grises peut être saisi pour tenter de débloquer la situation. La procédure et les coordonnées exactes sont détaillées sur service-public.gouv.fr, à vérifier avant toute démarche.`}}]}],c={slug:`carte-grise-ants-bloquee`,seo:{title:`Dossier carte grise bloqué sur l'ANTS : le débloquer`,description:`Dossier de carte grise bloqué sur l'ANTS ? Causes fréquentes, délais réels et recours, dont le passage par un professionnel habilité pour débloquer vite.`,canonical:`https://assutempo.fr/articles/carte-grise-ants-bloquee`,jsonLd:s},category:`Carte grise`,readTime:`7 min`,updatedDate:`30 juillet 2026`,author:`Evidence Assurances`,headline:`Dossier de carte grise bloqué sur l'ANTS : pourquoi, et comment le débloquer`,cta:{href:`/carte-grise`,label:`Débloquer mon dossier de carte grise`,title:`Certificat provisoire délivré sous 24 h ouvrées.`,subtitle:`Dossier vérifié avant transmission, saisie SIV par un professionnel habilité.`,suffix:`Sans rendez-vous.`},answerCapsule:{answer:`Un dossier de carte grise bloqué sur l'ANTS vient le plus souvent d'une pièce refusée (justificatif, photo, contrôle technique) ou d'un incident technique du portail. Il faut d'abord vérifier les notifications de l'espace personnel, puis relancer l'ANTS ou passer par un professionnel habilité, qui a un accès direct au système d'immatriculation (SIV) pour identifier et corriger le motif exact.`,facts:[{anchor:`1 mois`,text:`Délai légal pour immatriculer un véhicule après achat, à partir de la date du certificat de cession (article R322-5 du code de la route).`},{anchor:`135 €`,text:`Amende forfaitaire si le véhicule circule sans certificat d'immatriculation à jour passé ce délai, jusqu'à 750 € devant le tribunal (article 131-13 du code pénal, à vérifier sur service-public.gouv.fr).`},{anchor:`Médiateur des cartes grises`,text:`Recours possible en l'absence de réponse à une réclamation écrite adressée à l'ANTS, en complément du recours gracieux (service-public.gouv.fr).`},{anchor:`Accès direct au SIV`,text:`Un professionnel habilité par le Ministère de l'Intérieur peut traiter un dossier même pendant un incident sur le portail grand public de l'ANTS.`}],updated:`30 juillet 2026`},sections:[{type:`alert`,heading:`L'essentiel`,items:[`1 mois calendaire pour immatriculer un véhicule après achat, à partir de la date du certificat de cession (article R322-5 du code de la route).`,`Un dossier bloqué ne veut pas dire un dossier perdu : la grande majorité des blocages viennent d'une pièce refusée par le contrôle automatique, pas d'un problème de fond.`,`En cas de refus, un recours gracieux est possible via le téléservice ANTS ; en l'absence de réponse à une réclamation écrite, le médiateur des cartes grises peut être saisi (service-public.gouv.fr).`,`Un professionnel habilité par le Ministère de l'Intérieur a un accès direct au système d'immatriculation des véhicules (SIV) et peut redéposer un dossier corrigé, y compris pendant une panne du portail public.`]},{type:`table`,heading:`Quelles sont les causes de blocage les plus fréquentes, et comment les débloquer ?`,intro:`Un dossier « en cours d'examen » qui n'avance plus a presque toujours une cause identifiable. Voici les six situations les plus rencontrées, avec le délai de résolution habituel une fois le bon geste fait.`,columns:[`Cause de blocage`,`Délai de résolution habituel`,`Marche à suivre`],rows:[[`Justificatif de domicile refusé (plus de 6 mois, mauvais nom, scan illisible)`,`Quelques heures à 2-3 jours après renvoi du bon document`,`Reprendre une photo nette et cadrée, de moins de 6 mois, au nom du demandeur, puis la redéposer dans l'espace personnel`],[`Photo de pièce d'identité de mauvaise qualité`,`24 à 48 heures après correction`,`Scanner en haute résolution, les 4 coins visibles, sans reflet ni recadrage serré`],[`Contrôle technique expiré ou manquant (véhicule de plus de 4 ans)`,`Le temps d'obtenir un rendez-vous en centre de contrôle, variable selon la région`,`Faire réaliser ou renouveler le contrôle technique avant de redéposer le dossier`],[`Code de cession absent, expiré (15 jours) ou mal saisi`,`Dépend de la réactivité du vendeur : de quelques heures à plusieurs jours`,`Recontacter le vendeur pour qu'il régénère le code depuis son propre espace ANTS`],[`Incident technique ou panne du portail ANTS`,`Variable, parfois plusieurs jours sans visibilité sur le motif`,`Vérifier les notifications à intervalles réguliers, ou confier le dossier à un professionnel habilité, dont l'accès au SIV ne dépend pas du portail grand public`],[`Dossier affiché « en cours d'examen » sans motif ni notification`,`Au-delà d'une à deux semaines, la situation devient anormale`,`Contacter l'ANTS au 34 00, ou demander à un professionnel habilité un diagnostic direct dans le SIV`]],note:`Ces délais restent indicatifs : ils varient selon le département, la période de l'année et la charge du service instructeur. Vérifiez toujours l'avancement réel de votre dossier depuis votre espace personnel ANTS plutôt que de vous fier à une moyenne trouvée en ligne.`},{type:`text`,heading:`Pourquoi un dossier de carte grise reste-t-il bloqué sur l'ANTS ?`,paragraphs:[`Le système d'immatriculation des véhicules contrôle chaque pièce déposée de façon quasi automatique. Une photo prise en mode paysage, un justificatif de domicile au nom du conjoint plutôt que du demandeur, un scan flou : le dossier passe alors en attente, parfois sans message clair sur ce qui coince exactement.`,`Un conseiller Assutempo a récemment suivi le cas d'un client dont le dossier a été rejeté trois fois de suite pour la même raison : une photo du justificatif de domicile prise en biais, avec un coin coupé par le cadrage. Rien n'indiquait ce motif précis dans l'espace personnel, seulement la mention générique « pièce non conforme ». Le blocage a été levé en quelques heures une fois la bonne photo envoyée, format portrait, les quatre coins visibles.`,`D'autres blocages viennent d'un incident technique côté ANTS, sans rapport avec le dossier lui-même. Le portail peut afficher un statut figé pendant plusieurs jours en cas de maintenance ou de forte affluence, notamment lors des pics de renouvellement de contrôle technique en fin d'année.`]},{type:`text`,heading:`Combien de temps l'ANTS met-il normalement à traiter une demande de carte grise ?`,paragraphs:[`Les dossiers sont traités dans l'ordre chronologique d'arrivée, sans file prioritaire, une fois acceptés par le contrôle automatique. Le délai global dépend de la charge du service instructeur et varie sensiblement d'un département à l'autre : certains dossiers ressortent en quelques jours, d'autres prennent plusieurs semaines.`,`Aucun chiffre national fixe et garanti n'existe pour ce délai : il évolue avec la période de l'année et la disponibilité des équipes de France Titres. Le seul repère fiable reste le suivi affiché dans votre espace personnel ANTS, à vérifier sur service-public.gouv.fr en cas de doute sur un chiffre trouvé ailleurs.`]},{type:`timeline`,heading:`Dossier bloqué : la marche à suivre, jour par jour`,steps:[{num:1,title:`Jour 0 à 2 : vérifier les notifications de l'espace personnel`,body:`L'ANTS indique en général le motif précis dans les notifications de votre compte, ou dans le message reçu par email. Ce premier réflexe évite souvent d'attendre inutilement plusieurs jours pour une simple pièce à reprendre.`},{num:2,title:`Jour 2 à 5 : corriger et redéposer la pièce en cause`,body:`Reprenez la pièce identifiée en respectant les formats attendus (résolution suffisante, coins visibles, document non recadré) et redéposez-la depuis votre espace personnel, sans créer un second dossier.`},{num:3,title:`Jour 5 à 10 : relancer l'ANTS si aucun motif n'est indiqué`,body:`En l'absence totale d'information après quelques jours, contactez l'ANTS au 34 00 (numéro pour la France métropolitaine) pour un point de situation. Notez la date et le contenu de l'échange.`},{num:4,title:`Après 10 à 15 jours sans réponse : recours écrit ou professionnel habilité`,body:`Envoyez une réclamation écrite si le silence persiste, ou confiez le dossier à un professionnel habilité par le Ministère de l'Intérieur : son accès direct au SIV permet souvent d'identifier le blocage sans attendre un retour du service instructeur.`},{num:5,title:`Si le délai approche ou dépasse un mois sans solution`,body:`Vérifiez la validité de votre certificat provisoire d'immatriculation et rapprochez-vous du professionnel ou service qui suit le dossier pour un éventuel renouvellement. En cas de refus explicite resté sans réponse, le médiateur des cartes grises peut être saisi (service-public.gouv.fr).`}]},{type:`text`,heading:`Que faire si l'ANTS ne répond pas du tout à ma demande ?`,paragraphs:[`Deux situations bien distinctes se cachent derrière « l'ANTS ne répond pas » : un refus explicite de la demande, ou un silence total malgré une réclamation. En cas de refus, un recours gracieux est possible directement depuis le téléservice de l'ANTS, avec identification via FranceConnect ou l'application France Identité. Si ce recours n'aboutit pas, un courrier peut être adressé à la Délégation à la sécurité routière du ministère de l'Intérieur.`,`En l'absence de réponse à une réclamation écrite envoyée en recommandé, le médiateur des cartes grises peut être saisi pour tenter de débloquer la situation. La procédure exacte, les coordonnées et les délais indicatifs de traitement figurent sur service-public.gouv.fr : une vérification directe sur cette source reste le bon réflexe avant d'engager une démarche, les modalités pouvant évoluer.`,`Ne redéposez surtout pas un second dossier en parallèle pour « essayer autre chose ». Un doublon complique le traitement du dossier initial plutôt que de l'accélérer, et peut retarder l'ensemble.`]},{type:`decisionsplit`,question:`Le dossier est bloqué depuis plusieurs jours : attendre encore, ou passer par un professionnel habilité ?`,ariaLabel:`Comparaison entre attendre sur le portail ANTS et confier le dossier à un professionnel habilité`,voies:[{statut:`vigilance`,icon:n,titre:`Attendre et relancer seul sur le portail ANTS`,verdict:`Gratuit, adapté si le motif du blocage vient d'être identifié et qu'il suffit de renvoyer une pièce. Sans visibilité tant qu'aucune notification n'apparaît, l'attente peut s'étirer sans certitude sur l'issue.`},{statut:`ok`,icon:i,titre:`Confier le dossier à un professionnel habilité`,verdict:`Accès direct au système d'immatriculation des véhicules (SIV), diagnostic du motif exact et redépôt du dossier corrigé. Cette assistance a un coût, contrairement au dépôt direct sur l'ANTS, mais elle réduit le risque d'un nouveau refus.`}]},{type:`text`,heading:`Comment un professionnel habilité peut-il débloquer un dossier bloqué ?`,paragraphs:[`L'habilitation est accordée par le préfet, au nom du Ministère de l'Intérieur, à des professionnels de l'automobile qui signent une convention avec France Titres. Elle leur donne un accès direct au système d'immatriculation des véhicules (SIV), y compris pendant un incident sur le portail grand public, et leur permet de voir le motif exact d'un rejet plutôt que de deviner à partir d'un message générique.`,`Sur assutempo.fr, cette démarche passe par Certimat, qui agit comme intermédiaire technologique : la plateforme prépare et vérifie le dossier, puis le transmet à un professionnel habilité par le Ministère de l'Intérieur pour la saisie dans le SIV, ou à l'Agence Nationale des Titres Sécurisés selon le cas. Certimat n'est pas elle-même habilitée à saisir le SIV, et ne délivre aucun titre : le point à vérifier avant de confier un dossier urgent à une plateforme n'est donc pas un logo, mais qui saisit réellement.`,`Nuance à connaître avant de choisir cette voie : contrairement au dépôt direct et gratuit sur l'ANTS, l'accompagnement par un professionnel habilité a un coût. En échange, le dossier est vérifié avant transmission, ce qui réduit sensiblement le risque de repartir en bas de la pile pour une pièce manquante ou une photo illisible.`]},{type:`checklist`,heading:`Dossier bloqué : la checklist avant de recontacter l'ANTS`,intro:`Avant d'appeler ou d'écrire, réunissez ces éléments : ils font gagner du temps à l'ANTS comme à un professionnel habilité pour identifier la cause exacte.`,items:[`Le numéro de dossier et la date de dépôt initiale`,`Une capture des notifications ou du dernier message reçu, s'il y en a un`,`Un justificatif de domicile de moins de 6 mois, au nom exact du demandeur`,`La date de validité du code de cession, remis par le vendeur, et sa date de génération`,`Le contrôle technique en cours de validité si le véhicule a plus de 4 ans`,`La date d'expiration du certificat provisoire d'immatriculation en cours, si un CPI a déjà été délivré`]},{type:`text`,heading:`Un blocage lié au changement de titulaire : un cas fréquent`,paragraphs:[`Une part notable des dossiers bloqués vient en réalité d'un changement de titulaire mal engagé : code de cession expiré après 15 jours sans avoir été utilisé, ancienne carte grise non barrée ou non datée, ou informations du vendeur qui ne correspondent plus à son propre compte ANTS. Le dossier de l'acheteur reste alors en attente d'un document que lui seul ne peut pas produire.`],relatedLink:{text:`Le guide complet du changement de titulaire, étape par étape`,href:`/articles/changement-titulaire-carte-grise`}},{type:`text`,heading:`Quel est le délai légal, et que risque-t-on si le blocage dépasse un mois ?`,paragraphs:[`Le délai légal d'un mois calendaire pour immatriculer un véhicule après achat ne s'arrête pas parce que le dossier est bloqué sur l'ANTS (article R322-5 du code de la route). Ce que la loi sanctionne, c'est le fait de maintenir le véhicule en circulation sans certificat d'immatriculation à jour, indépendamment de la raison du retard.`,`Un contrôle routier expose alors à une amende forfaitaire de 135 €, jusqu'à 750 € devant le tribunal, plafond des contraventions de 4e classe (article 131-13 du code pénal). Ces montants sont ceux communément cités pour ce type d'infraction : à vérifier sur service-public.gouv.fr avant tout paiement, les barèmes pouvant évoluer.`],relatedLink:{text:`Les délais réels du certificat provisoire et de la carte grise définitive`,href:`/articles/combien-de-temps-carte-grise`}},{type:`text`,heading:`Puis-je rouler pendant que mon dossier de carte grise reste bloqué ?`,paragraphs:[`Avec un certificat provisoire d'immatriculation (CPI) encore valide, oui, en France uniquement, pendant sa durée d'un mois. Passé cette date, mieux vaut vérifier l'avancement réel du dossier et solliciter un renouvellement plutôt que de continuer à circuler avec un document expiré.`,`L'obligation d'assurance, elle, ne dépend jamais de l'état du dossier de carte grise : elle s'applique dès le premier trajet, CPI en poche ou dossier bloqué depuis des semaines. C'est même souvent le seul point réglé rapidement pendant qu'un dossier administratif traîne, une assurance temporaire délivrant une attestation par email en quelques minutes.`],relatedLink:{text:`Rouler en attendant sa carte grise définitive avec une assurance temporaire`,href:`/articles/assurance-temporaire-rouler-en-attendant-carte-grise`}}],faqItems:[{q:`Pourquoi mon dossier de carte grise reste-t-il bloqué sur le site de l'ANTS ?`,a:`Le plus souvent à cause d'une pièce refusée par le contrôle automatique : justificatif de domicile trop ancien ou mal nommé, photo d'identité illisible, contrôle technique expiré, ou code de cession expiré après 15 jours. Un incident technique ponctuel sur le portail est aussi possible, sans lien avec votre dossier.`},{q:`Combien de temps l'ANTS met-il normalement à traiter une demande de carte grise ?`,a:`Les demandes sont traitées dans l'ordre d'arrivée, sans possibilité d'accélération une fois le dossier accepté. Le délai varie fortement selon le département et la charge du service instructeur : vérifiez l'avancement réel depuis votre espace personnel ANTS plutôt que de vous fier à une moyenne.`},{q:`Que faire si l'ANTS ne répond pas du tout à ma demande ?`,a:`En l'absence de réponse à une réclamation écrite, vous pouvez saisir le médiateur des cartes grises (service-public.gouv.fr). En cas de refus explicite, un recours gracieux est possible via le téléservice de l'ANTS, puis un appel auprès du ministère de l'Intérieur si le recours n'aboutit pas.`},{q:`Un professionnel habilité peut-il débloquer un dossier plus vite que l'ANTS en direct ?`,a:`Souvent oui, pour la partie diagnostic et redépôt : il a un accès direct au système d'immatriculation des véhicules (SIV) et peut identifier le motif exact du blocage, y compris pendant un incident sur le portail public. Cette assistance a un coût, contrairement au dépôt en direct sur l'ANTS.`},{q:`Puis-je rouler si mon dossier de carte grise est bloqué depuis plus d'un mois ?`,a:`Pas avec un certificat provisoire d'immatriculation expiré : mieux vaut vérifier l'avancement du dossier et solliciter un renouvellement auprès du professionnel ou du service qui le suit. L'assurance, elle, reste obligatoire sans exception, quel que soit l'état du dossier de carte grise.`},{q:`Comment saisir le médiateur des cartes grises en cas de refus ou de silence prolongé ?`,a:`Après une réclamation écrite restée sans réponse satisfaisante auprès de l'ANTS, le médiateur des cartes grises peut être saisi pour tenter de débloquer la situation. La procédure et les coordonnées exactes sont détaillées sur service-public.gouv.fr, à vérifier avant toute démarche.`}]}}));function u(){return(0,d.jsx)(o,{data:c})}var d;e((()=>{a(),l(),d=t()}))();export{u as default};